import pandas as pd
import numpy as np

def clean(df):
    d = df.copy()

    for col in ["species", "island", "sex"]:
        if col in d.columns:
            d[col] = d[col].astype("string").str.strip()

    species_map = {
        "adelie": "Adelie",
        "adeile": "Adelie",
        "chinstrap": "Chinstrap",
        "gentoo": "Gentoo",
        "gentto": "Gentoo",
    }
    if "species" in d.columns:
        d["species"] = d["species"].str.lower().map(species_map).fillna(d["species"])

    island_map = {
        "biscoe": "Biscoe",
        "dream": "Dream",
        "torgersen": "Torgersen",
    }
    if "island" in d.columns:
        d["island"] = d["island"].str.lower().map(island_map).fillna(d["island"])

    if "sex" in d.columns:
        d["sex"] = d["sex"].str.lower()
        d.loc[~d["sex"].isin(["male", "female"]), "sex"] = pd.NA

    for col in ["bill_length_mm", "bill_depth_mm", "flipper_length_mm", "year"]:
        if col in d.columns:
            d[col] = pd.to_numeric(d[col], errors="coerce")

    if "body_mass_g" in d.columns:
        s = d["body_mass_g"].astype("string")
        s = s.str.replace(",", "", regex=False).str.replace(" ", "", regex=False)
        s = pd.to_numeric(s, errors="coerce")

        repair = (s > 6500) & ((s / 1000) >= 2500) & ((s / 1000) <= 6500)
        s.loc[repair] = s.loc[repair] / 1000

        s = s.mask((s < 2500) | (s > 6500))
        d["body_mass_g"] = s

    return d

def answer(df):
    d = clean(df)
    d = d[d["species"].isin(["Adelie", "Chinstrap", "Gentoo"])]
    d = d.dropna(subset=["species", "body_mass_g"])
    result = d.groupby("species", sort=False)["body_mass_g"].mean()
    return {str(k): float(v) for k, v in result.items()}
